<!-- MODAL & OFFCANVAS -->
<div class="modal fade" id="m" tabindex="-1"><div class="modal-dialog modal-dialog-centered" id="mDialog"><div class="modal-content" id="mBody"></div></div></div>
<div class="offcanvas offcanvas-end" tabindex="-1" id="oc" style="width:520px"><div class="offcanvas-header pb-0"><button type="button" class="btn-close ms-auto" data-bs-dismiss="offcanvas"></button></div><div class="offcanvas-body px-4 pt-0" id="ocBody"></div></div>
<div class="toast-container position-fixed bottom-0 start-50 translate-middle-x p-3" style="z-index:2100">
  <div id="toast" class="toast align-items-center" role="status"><div class="d-flex"><div class="toast-body" id="toastMsg"></div><button type="button" class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast"></button></div></div>
</div>
<div class="tip" id="tip"></div>
